    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: At what age is an infant typically expected to first develop a social smile in response to a human face?', '["1 month", "2 months", "4 months", "6 months"]', 1, 'The social smile classically appears at 2 months (8 weeks) of age. (Nelson)'),
    (v_topic_id, '2: By what age should a child typically be able to sit unsupported without propping on their hands?', '["4 months", "6 months", "8 months", "10 months"]', 1, 'At 6 months, infants sit with support (tripod). Independent, unsupported sitting is typically mastered by 8 months. (Nelson)'),
    (v_topic_id, '3: At what age does an infant typically roll from prone (tummy) to supine (back)?', '["2 months", "4 months", "6 months", "8 months"]', 1, 'Rolling from front to back typically occurs at 4 months. Back to front occurs later, around 5-6 months. (Case Files)'),
    (v_topic_id, '4: By what age is a healthy term infant expected to double their birth weight?', '["2-3 months", "4-5 months", "6-8 months", "12 months"]', 1, 'Birth weight typically doubles by 4-5 months and triples by 12 months. (Harriet Lane)'),
    (v_topic_id, '5: At what age does a child typically begin to use a mature pincer grasp (thumb and index finger)?', '["6 months", "9 months", "12 months", "15 months"]', 1, 'The crude pincer grasp appears around 9 months, and the mature, refined pincer grasp is mastered by 12 months. (Nelson)'),
    (v_topic_id, '6: A parent asks when their child should say their first clear, specific word (e.g., pointing to dad and saying "Dada"). What is the expected age?', '["9 months", "12 months", "15 months", "18 months"]', 1, 'Saying "mama" or "dada" specifically, plus 1-2 other words, is a classic 12-month milestone. (Case Files)'),
    (v_topic_id, '7: Stranger anxiety, the normal developmental fear of unfamiliar people, typically begins at what age?', '["4 months", "6 months", "9 months", "12 months"]', 1, 'Stranger anxiety peaks between 9 and 12 months but classically begins around 6-9 months. (Nelson)'),
    (v_topic_id, '8: Separation anxiety, the distress when a primary caregiver leaves, typically emerges at what age?', '["6 months", "9 months", "12 months", "18 months"]', 1, 'Separation anxiety emerges around 9 months and peaks between 12 and 18 months. (Case Files)'),
    (v_topic_id, '9: At what age should a child typically be able to walk independently?', '["9-10 months", "12-15 months", "18-20 months", "24 months"]', 1, 'While some walk at 10-11 months, independent walking is typically expected by 12-15 months. Failure to walk by 18 months requires evaluation. (Nelson)'),
    (v_topic_id, '10: A 2-year-old child presents for a well-child check. How many words should they typically have in their vocabulary?', '["10-20 words", "50+ words", "150+ words", "500+ words"]', 1, 'A 2-year-old typically has a vocabulary of 50-200 words and strings 2 words together. (Harriet Lane)'),
    (v_topic_id, '11: At what age is a child expected to have speech that is 50% intelligible to a stranger?', '["1 year", "2 years", "3 years", "4 years"]', 1, 'Rule of 4s: Speech should be 50% intelligible at 2 years, 75% at 3 years, and 100% at 4 years. (Case Files)'),
    (v_topic_id, '12: At what age should a child be able to stack a tower of 6 cubes?', '["15 months", "18 months", "24 months", "36 months"]', 2, 'A 2-year-old (24 months) can typically build a tower of 6 cubes. (Nelson)'),
    (v_topic_id, '13: At what age should a child be able to draw a recognizable circle?', '["2 years", "3 years", "4 years", "5 years"]', 1, 'Drawing shapes follows a sequence: Line (2y), Circle (3y), Cross (4y), Square (4y), Triangle (5y). (Case Files)'),
    (v_topic_id, '14: A child is observed running well, kicking a ball, and walking up stairs one step at a time (marking time). What is the most likely age?', '["18 months", "2 years", "3 years", "4 years"]', 1, 'These are classic 2-year-old (24 months) gross motor milestones. (Nelson)'),
    (v_topic_id, '15: At what age does a child typically learn to ride a tricycle?', '["2 years", "3 years", "4 years", "5 years"]', 1, 'Riding a tricycle is a classic 3-year-old (36 months) gross motor milestone. (Harriet Lane)'),
    (v_topic_id, '16: A 3-year-old child should be able to do which of the following fine motor tasks?', '["Use a spoon well without spilling", "Draw a cross", "Tie shoelaces", "Use scissors to cut a complex shape"]', 0, 'A 3-year-old can use a spoon/fork, copy a circle, and build a tower of 9 cubes. Drawing a cross is 4 years. (Case Files)'),
    (v_topic_id, '17: What type of play is most characteristic of a 2-year-old child?', '["Solitary play", "Parallel play", "Associative play", "Cooperative play"]', 1, 'Two-year-olds engage in parallel play (playing next to each other but not with each other). (Nelson)'),
    (v_topic_id, '18: When does the anterior fontanelle typically close?', '["2-4 months", "9-18 months", "24-30 months", "3 years"]', 1, 'The posterior fontanelle closes early (1-2 months), but the anterior closes between 9 and 18 months. (Harriet Lane)'),
    (v_topic_id, '19: A parent is concerned because their 6-month-old infant is not yet crawling. What is the appropriate response?', '["Refer to early intervention immediately", "Reassure the parent that crawling typically occurs between 7 and 9 months", "Order an MRI of the brain", "Check a CK level for muscular dystrophy"]', 1, 'Crawling (creeping) on hands and knees usually develops around 8-9 months. (Case Files)'),
    (v_topic_id, '20: What is the defining characteristic of "object permanence"?', '["Recognizing a parent''s face", "Understanding that an object continues to exist even when it cannot be seen", "Fearing strangers", "Pointing to an object of interest"]', 1, 'Object permanence typically develops around 9 months of age (Piaget''s sensorimotor stage). (Nelson)'),
    (v_topic_id, '21: Which developmental red flag requires immediate evaluation in an 18-month-old child?', '["Inability to copy a circle", "Absence of pointing to share interest (joint attention)", "Vocabulary of only 30 words", "Inability to jump with two feet"]', 1, 'Lack of joint attention or pointing by 18 months is a major red flag for autism spectrum disorder. (Case Files)'),
    (v_topic_id, '22: The Moro reflex typically disappears by what age?', '["1 month", "3-4 months", "6-8 months", "12 months"]', 1, 'Primitive reflexes like the Moro and palmar grasp disappear around 3-4 months to allow for voluntary motor control. (Nelson)'),
    (v_topic_id, '23: The asymmetric tonic neck reflex (fencer posture) typically disappears by what age?', '["2 months", "4 months", "6 months", "9 months"]', 1, 'It must disappear by 4-6 months to allow the infant to roll and bring hands to the midline. (Harriet Lane)'),
    (v_topic_id, '24: A 4-month-old infant who consistently keeps their hands tightly fisted should be evaluated for:', '["Autism", "Cerebral palsy (spasticity)", "Muscular dystrophy", "Normal development"]', 1, 'Hands should be predominantly open by 3-4 months. Persistent fisting is a sign of upper motor neuron dysfunction. (Case Files)'),
    (v_topic_id, '25: At what age should a child be able to hop on one foot?",', '["2 years", "3 years", "4 years", "5 years"]', 2, 'Hopping on one foot is a classic 4-year-old gross motor milestone. (Nelson)'),
    (v_topic_id, '26: A child can count 10 or more objects, correctly name at least 4 colors, and understands the concept of "future." What is their likely age?",', '["3 years", "4 years", "5 years", "6 years"]', 2, 'These are typical cognitive milestones for a 5-year-old entering kindergarten. (Case Files)'),
    (v_topic_id, '27: At what age does the parachute reflex (extending arms when falling forward) typically appear, and when does it disappear?",', '["Appears at 2 months, disappears at 6 months", "Appears at 6-8 months, never disappears", "Appears at 12 months, disappears at 2 years", "Appears at birth, disappears at 4 months"]', 1, 'The parachute is a protective postural reflex that develops right before crawling/walking and persists for life. (Nelson)'),
    (v_topic_id, '28: A child''s birth length is typically 50 cm (20 inches). By what age does a child typically double their birth length?",', '["1 year", "2 years", "3 years", "4 years"]', 3, 'Length increases by 50% at 1 year (75 cm) and doubles by 4 years (100 cm or 40 inches). (Harriet Lane)'),
    (v_topic_id, '29: At what age do the first primary (deciduous) teeth typically erupt?",', '["2-4 months", "6-8 months", "10-12 months", "15-18 months"]', 1, 'The mandibular central incisors are usually the first to erupt at 6-8 months. (Nelson)'),
    (v_topic_id, '30: A 12-month-old infant is still exclusively breastfed and refuses solid foods. They have pale conjunctivae. What is the most likely nutritional deficiency?",', '["Vitamin D", "Iron", "Vitamin B12", "Vitamin C"]', 1, 'Breast milk is a poor source of iron. Iron stores deplete by 4-6 months; solid foods (iron-fortified) are needed. (Case Files)'),
    (v_topic_id, '31: At what age is the M-CHAT (Modified Checklist for Autism in Toddlers) formally administered during well-child checks?",', '["12 months", "18 and 24 months", "3 years", "5 years"]', 1, 'The AAP recommends universal autism screening at 18 and 24 months. (Nelson)'),
    (v_topic_id, '32: A 3-year-old child should be able to dress themselves with supervision. Which task is appropriate for this age?",', '["Buttoning a shirt", "Zipping a jacket", "Putting on shoes (no laces) and pulling down pants", "Tying shoelaces"]', 2, 'Unbuttoning and unzipping occur around 3; buttoning/zipping occurs at 4; tying shoes at 5. (Case Files)'),
    (v_topic_id, '33: At what age does a child typically begin to use pronouns (I, me, you) correctly?",', '["18 months", "2 years", "3 years", "4 years"]', 2, 'Two-year-olds often refer to themselves by name. Three-year-olds master basic pronouns. (Nelson)'),
    (v_topic_id, '34: What is the typical age range for a child to achieve daytime bowel and bladder control (toilet training)?",', '["12-18 months", "18-24 months", "2-3 years", "4-5 years"]', 2, 'Most children are physically and cognitively ready to toilet train between 2 and 3 years of age. (Harriet Lane)'),
    (v_topic_id, '35: A child can walk down stairs alternating feet. What is their likely age?",', '["2 years", "3 years", "4 years", "5 years"]', 2, 'Walking UP stairs alternating feet is 3 years; walking DOWN alternating feet is 4 years. (Case Files)'),
    (v_topic_id, '36: A 4-month-old infant is pulled to a sitting position. Which of the following is an expected finding?",', '["Complete head lag", "No head lag (head stays in line with the torso)", "The infant stands up", "The infant rolls over"]', 1, 'Significant head lag after 4-5 months is a red flag for hypotonia or motor delay. (Nelson)'),
    (v_topic_id, '37: At what age does an infant typically begin to transfer an object from one hand to the other?",', '["4 months", "6 months", "9 months", "12 months"]', 1, 'Hand-to-hand transfer across the midline is a classic 6-month fine motor milestone. (Case Files)'),
    (v_topic_id, '38: A 9-month-old infant is playing with a toy. The parent covers the toy with a blanket. What will the infant do?",', '["Cry and look away", "Search for the toy under the blanket", "Fall asleep", "Throw the blanket"]', 1, 'This demonstrates object permanence, which develops by 9 months. (Nelson)'),
    (v_topic_id, '39: A child knows their age, gender, and can tell a story. They can copy a cross. What is their age?",', '["2 years", "3 years", "4 years", "5 years"]', 2, 'These are classic 4-year-old milestones. (Harriet Lane)'),
    (v_topic_id, '40: At what age is a child expected to know their first and last name, and their phone number/address?",', '["3 years", "4 years", "5 years", "6 years"]', 2, 'This is a kindergarten-readiness milestone achieved around 5 years of age. (Case Files)'),
    (v_topic_id, '41: A parent brings in a 15-month-old who is not yet walking. The child crawls rapidly and pulls to a stand. What is the best management?",', '["Refer to pediatric neurology", "Order an MRI", "Reassure the parent and follow up at 18 months", "Check a CK level"]', 2, 'While many walk by 12 months, the cutoff for normal independent walking is 18 months. (Nelson)'),
    (v_topic_id, '42: Which of the following is a normal visual milestone for a 2-month-old infant?",', '["Tracking an object past the midline (180 degrees)", "Reaching for a dangling ring", "Recognizing colors", "Having 20/20 vision"]', 0, 'Tracking past the midline is expected by 2-3 months. (Case Files)'),
    (v_topic_id, '43: At what age should an infant typically respond to their own name?",', '["2 months", "6 months", "12 months", "18 months"]', 1, 'Turning to their name is an expected receptive language milestone by 6-9 months. (Nelson)'),
    (v_topic_id, '44: A 2-year-old child should be able to follow a command with how many steps?",', '["1 step", "2 steps", "3 steps", "4 steps"]', 1, 'A 2-year-old follows 2-step commands (e.g., "Pick up the ball and give it to Daddy"). (Harriet Lane)'),
    (v_topic_id, '45: A 3-year-old child should be able to follow a command with how many steps?",', '["1 step", "2 steps", "3 steps", "4 steps"]', 2, 'A 3-year-old follows 3-step commands. (Case Files)'),
    (v_topic_id, '46: At what age does "imaginative play" (e.g., pretending a block is a phone) typically begin?",', '["12 months", "18-24 months", "3 years", "5 years"]', 1, 'Symbolic or imaginative play emerges between 18 and 24 months. (Nelson)'),
    (v_topic_id, '47: A 6-month-old infant is being examined. Which reflex should NO LONGER be present?",', '["Parachute", "Babinski", "Rooting", "Patellar tendon"]', 2, 'Primitive reflexes like rooting, Moro, and palmar grasp should disappear by 4-6 months. Babinski can persist until 1-2 years. (Case Files)'),
    (v_topic_id, '48: The Babinski reflex (upgoing plantar reflex) is considered normal up to what age in a healthy child?",', '["6 months", "12-24 months", "3 years", "5 years"]', 1, 'It typically disappears as the corticospinal tract myelinates, usually by 1-2 years of age. (Nelson)'),
    (v_topic_id, '49: By what age is a child expected to consistently identify their own gender (boy or girl)?",', '["18 months", "3 years", "5 years", "7 years"]', 1, 'Gender identity is usually established around 3 years of age. (Harriet Lane)'),
    (v_topic_id, '50: A 4-year-old child engages in "cooperative play." What does this mean?",', '["Playing alone", "Playing next to others but not interacting", "Playing a game with rules and a shared goal with other children", "Copying others"]', 2, 'Cooperative play is a 4-year-old milestone. (Nelson)'),
    (v_topic_id, '51: A 5-year-old child should be able to copy which of the following shapes?",', '["Circle", "Cross", "Triangle", "Diamond"]', 2, 'Circle (3), Cross (4), Triangle (5), Diamond (6). (Case Files)'),
    (v_topic_id, '52: At what age should a child be able to tie their own shoelaces?",', '["3 years", "4 years", "5 years", "7 years"]', 2, 'Tying shoes is a complex fine motor task achieved at 5 years. (Nelson)'),
    (v_topic_id, '53: A child presents with delayed speech, lack of eye contact, and repetitive hand-flapping. What is the most likely diagnosis?",', '["Hearing loss", "Autism Spectrum Disorder", "Global Developmental Delay", "Cerebral Palsy"]', 1, 'Classic triad of impaired social communication, restricted interests, and repetitive behaviors. (Case Files)'),
    (v_topic_id, '54: A 2-year-old child has no words and does not respond to loud noises. What is the absolute FIRST test that must be ordered?",', '["MRI brain", "EEG", "Audiology evaluation (Hearing test)", "Genetic microarray"]', 2, 'Hearing loss must be ruled out FIRST in any child with a speech delay. (Nelson)'),
    (v_topic_id, '55: At what age does "stranger anxiety" typically resolve or significantly diminish?",', '["12 months", "18-24 months", "3 years", "5 years"]', 1, 'It peaks around 12 months and resolves by 2 years as the child gains cognitive understanding. (Harriet Lane)'),
    (v_topic_id, '56: A child points to objects not just to request them, but to share interest with a parent (e.g., pointing to an airplane). This is called:",', '["Echolalia", "Joint attention", "Object permanence", "Theory of mind"]', 1, 'A critical social milestone achieved by 12-18 months. Its absence is a red flag for autism. (Case Files)'),
    (v_topic_id, '57: At what age should a child be able to build a tower of 3 cubes?",', '["12 months", "15 months", "18 months", "24 months"]', 2, 'Tower milestones: 2 cubes (15m), 3 cubes (18m), 6 cubes (24m), 9 cubes (36m). (Nelson)'),
    (v_topic_id, '58: A child is observed scribbling randomly with a crayon. What is the expected age?",', '["12 months", "15-18 months", "24 months", "3 years"]', 1, 'Spontaneous scribbling begins around 15-18 months. (Case Files)'),
    (v_topic_id, '59: A child can draw a person with 6 body parts. What is their expected age?",', '["3 years", "4 years", "5 years", "6 years"]', 2, 'A 4-year-old draws a person with 3 parts; a 5-year-old draws a person with 6 parts. (Nelson)'),
    (v_topic_id, '60: At what age should a child understand the concepts of "right" and "left" on their own body?",', '["3 years", "4 years", "5 years", "6 years"]', 2, 'This complex spatial understanding develops around age 5. (Harriet Lane)'),
    (v_topic_id, '61: A 6-month-old infant is not babbling (producing consonant-vowel combinations like "ba-ba" or "da-da"). Is this normal?",', '["Yes, babbling starts at 9 months", "No, babbling should begin by 6 months. Absence requires evaluation.", "Yes, babbling starts at 12 months", "None"]', 1, 'Cooing is 2 months; babbling is 6 months. (Case Files)'),
    (v_topic_id, '62: A child can say their first and last name, understands prepositions (under, on, behind), and asks "why" constantly. What is their age?",', '["2 years", "3 years", "4 years", "5 years"]', 1, 'The "why" phase and prepositions are classic 3-year-old milestones. (Nelson)'),
    (v_topic_id, '63: Which of the following fine motor skills is expected of a 4-year-old?",', '["Using a knife to spread butter", "Using scissors to cut out a picture", "Tying shoelaces", "Stacking 3 blocks"]', 1, 'A 4-year-old can use scissors successfully. (Case Files)'),
    (v_topic_id, '64: A 2-month-old infant should be able to do which of the following in the prone position?",', '["Roll over", "Lift their head 45 degrees", "Sit up", "Crawl"]', 1, 'Lifting the head off the bed while prone is an early gross motor milestone. (Nelson)'),
    (v_topic_id, '65: At what age does an infant typically display a "raking" grasp (using all fingers to pull an object toward them)?",', '["4 months", "6 months", "9 months", "12 months"]', 1, 'Raking occurs at 6 months, before the pincer grasp develops at 9-12 months. (Harriet Lane)'),
    (v_topic_id, '66: An infant can confidently pick up a Cheerio using the pads of their thumb and index finger. This is a mature pincer grasp. What age?",', '["6 months", "9 months", "12 months", "15 months"]', 2, 'The 9-month pincer is "crude" (sides of fingers). 12 months is mature (pads). (Case Files)'),
    (v_topic_id, '67: A child says "mama" but applies it to everyone, including strangers and pets. This is "non-specific" mama/dada. What age?",', '["6 months", "9 months", "12 months", "15 months"]', 1, 'Non-specific mama/dada occurs at 9 months. Specific (only for the parents) occurs at 12 months. (Nelson)'),
    (v_topic_id, '68: At what age should a child be able to name 4 primary colors?",', '["2 years", "3 years", "4 years", "5 years"]', 3, 'Knowing colors is a 4-year-old milestone. (Case Files)'),
    (v_topic_id, '69: A 4-year-old child should be able to balance on one foot for how long?",', '["1 second", "2 seconds", "10 seconds", "They cannot do this"]', 1, 'Balancing for 2 seconds is 4 years; balancing for 10 seconds is 5 years. (Nelson)'),
    (v_topic_id, '70: At what age does an infant typically begin to drink from a cup with assistance?",', '["6 months", "9 months", "12 months", "18 months"]', 1, 'A 9-month-old can hold a bottle and drink from a cup with help. (Harriet Lane)'),
    (v_topic_id, '71: A child can confidently use a spoon with minimal spilling. What age?",', '["12 months", "15 months", "18 months", "24 months"]', 3, 'Spoon use begins around 15-18 months, but proficiency is achieved by 24 months. (Case Files)'),
    (v_topic_id, '72: What is the normal visual acuity of a newborn infant?",', '["20/20", "20/40", "20/400 (can only see objects 8-12 inches away)", "Blind"]', 2, 'Newborns are extremely nearsighted. Vision matures to 20/20 by age 3-5. (Nelson)'),
    (v_topic_id, '73: A mother is worried because her 2-year-old is a "picky eater" and refuses many foods, preferring only chicken nuggets. Weight gain is normal. Diagnosis?",', '["ARFID", "Normal toddler physiologic anorexia and food jags", "Anorexia nervosa", "Celiac disease"]', 1, 'As growth velocity slows at age 2, appetite decreases, and toddlers exert autonomy via food jags. (Case Files)'),
    (v_topic_id, '74: At what age is it developmentally appropriate to introduce solid foods to an infant?",', '["2 months", "4-6 months", "9 months", "12 months"]', 1, 'Solids are introduced when the extrusion reflex disappears and the infant can sit with support. (Nelson)'),
    (v_topic_id, '75: A 12-month-old should be drinking what type of milk?",', '["Breast milk or infant formula", "Whole cow''s milk", "Skim milk", "Almond milk"]', 1, 'Infants transition from formula to whole cow''s milk at 12 months to support brain growth. (Harriet Lane)'),
    (v_topic_id, '76: When can a child be transitioned from whole milk to 2% or skim milk?",', '["12 months", "18 months", "2 years", "5 years"]', 2, 'The fat in whole milk is required for myelination until age 2. (Case Files)'),
    (v_topic_id, '77: A 6-month-old infant is exclusively breastfed. What daily supplement do they strictly require?",', '["Vitamin C", "Vitamin D (400 IU/day) and Iron", "Calcium", "Zinc"]', 1, 'Breast milk lacks adequate Vitamin D and iron stores deplete by 6 months. (Nelson)'),
    (v_topic_id, '78: A child can ride a bicycle without training wheels. What is the expected age?",', '["3 years", "4 years", "5 years", "6-7 years"]', 3, 'This requires advanced balance and coordination, usually achieved by 6 years. (Harriet Lane)'),
    (v_topic_id, '79: A child is observed playing a board game with peers, taking turns, and following rules. What age?",', '["2 years", "3 years", "4 years", "5-6 years"]', 3, 'Rule-based cooperative play is characteristic of school-aged children (5+). (Case Files)'),
    (v_topic_id, '80: At what age does a child typically understand the concept of death as permanent and irreversible?",', '["3 years", "5 years", "7-9 years", "12 years"]', 2, 'Before age 7, children often view death as temporary or a state of sleep. (Nelson)'),
    (v_topic_id, '81: A child can count to 10 by rote memory but cannot point to 3 objects and count them. What age?",', '["2 years", "3 years", "4 years", "5 years"]', 1, 'Rote counting starts at 3, but 1-to-1 correspondence counting develops at 4-5 years. (Case Files)'),
    (v_topic_id, '82: A 15-month-old child does not use any words and does not point. They have a history of recurrent otitis media. Next step?",', '["Autism screening", "Audiology evaluation", "Speech therapy referral", "All of the above"]', 3, 'Recurrent ear infections are a major risk factor for conductive hearing loss causing speech delay. (Nelson)'),
    (v_topic_id, '83: A parent asks when they should start reading to their infant. What is the AAP recommendation?",', '["6 months", "12 months", "2 years", "From birth"]', 3, 'Early literacy promotion should begin at birth to foster language development. (Harriet Lane)'),
    (v_topic_id, '84: At what age does an infant typically start exhibiting the "extrusion reflex" (pushing food out of the mouth with the tongue)?",', '["Birth to 4 months", "6-9 months", "12 months", "2 years"]', 0, 'This reflex must disappear (around 4-6 months) before spoon-feeding solids can begin. (Case Files)'),
    (v_topic_id, '85: A child has an vocabulary of 5 words at 18 months. Is this normal?",', '["Yes", "No, an 18-month-old should have 10-25 words", "Yes, boys speak later", "None"]', 1, 'Less than 10 words at 18 months warrants close monitoring and possible early intervention. (Nelson)'),
    (v_topic_id, '86: A child can tell a detailed story, use future tense, and their speech is 100% intelligible. Age?",', '["2 years", "3 years", "4 years", "5 years"]', 2, '100% intelligibility is the hallmark of a 4-year-old. (Case Files)'),
    (v_topic_id, '87: A 2-year-old child throws a massive temper tantrum in the grocery store when denied a toy. What is the most appropriate advice for the parent?",', '["Spank the child", "Give them the toy to calm them down", "Ignore the behavior (extinction) as long as the child is safe", "Reason with the child"]', 2, 'Tantrums are normal at age 2; negative behaviors should be ignored to prevent reinforcement. (Nelson)'),
    (v_topic_id, '88: At what age should a child be transitioned from a crib to a toddler bed?",', '["12 months", "18 months", "When they are 35 inches tall or can climb out of the crib (usually 2-3 years)", "4 years"]', 2, 'Safety (preventing falls) is the primary indicator for transitioning. (Harriet Lane)'),
    (v_topic_id, '89: When is the AAP recommended age to stop using a pacifier to prevent dental malocclusion?",', '["6 months", "12 months", "By 2-3 years of age at the latest", "5 years"]', 2, 'Prolonged use alters the shape of the hard palate. (Case Files)'),
    (v_topic_id, '90: A child can undress themselves completely but needs help putting clothes on. Age?",', '["2 years", "3 years", "4 years", "5 years"]', 1, 'Taking clothes off is mastered before putting them on (usually 3 years). (Nelson)'),
    (v_topic_id, '91: At what age is an infant expected to reach for an object across the midline?",', '["2 months", "4 months", "6 months", "9 months"]', 2, 'Crossing the midline is a 6-month milestone. (Case Files)'),
    (v_topic_id, '92: A 3-month-old infant is placed in the prone position. They should be able to lift their head and chest, bearing weight on what?",', '["Their face", "Their forearms", "Their extended hands", "Their knees"]', 1, 'Forearm weight-bearing is 3 months; extended arm weight-bearing is 4-5 months. (Nelson)'),
    (v_topic_id, '93: At what age should an infant be able to pull themselves up to a standing position using furniture?",', '["6 months", "9 months", "12 months", "15 months"]', 1, 'Pulling to stand and "cruising" along furniture occurs around 9-10 months. (Harriet Lane)'),
    (v_topic_id, '94: A 12-month-old infant is taking their first independent steps. Their arms are held high and their feet are wide apart. Is this normal?",', '["No, indicates ataxia", "Yes, this is the classic ''''high guard'''' wide-based gait of a new walker", "No, indicates cerebral palsy", "None"]', 1, 'The gait normalizes and narrows over the next 6-12 months. (Case Files)'),
    (v_topic_id, '95: A child can walk backwards. What is the earliest age this is typically seen?",', '["12 months", "15-18 months", "24 months", "36 months"]', 1, 'Walking backwards and running stiffly emerge around 15-18 months. (Nelson)'),
    (v_topic_id, '96: What is the most common cause of language delay in a toddler?",', '["Autism", "Conductive hearing loss (often secondary to recurrent otitis media)", "Intellectual disability", "Expressive language disorder"]', 1, 'Always check the ears and order an audiogram. (Case Files)'),
    (v_topic_id, '97: A 2-month-old infant does NOT have a social smile and does not track objects. Next step?",', '["Reassure", "Immediate developmental and neurological evaluation", "Wait until 4 months", "Check lead level"]', 1, 'Absence of milestones by their upper limit of normal is a red flag. (Nelson)'),
    (v_topic_id, '98: At what age does the American Academy of Pediatrics recommend universal developmental screening (using a validated tool like ASQ) during well-child checks?",', '["9, 18, and 30 months", "12 and 24 months", "Only if parents have concerns", "At every single visit"]', 0, 'Autism screening is 18/24m; broad developmental screening is 9/18/30m. (Harriet Lane)'),
    (v_topic_id, '99: A child is observed playing "peek-a-boo" and "pat-a-cake." What age?",', '["4 months", "6 months", "9 months", "12 months"]', 2, 'These interactive games require object permanence and imitation, emerging at 9 months. (Case Files)'),
    (v_topic_id, '100: A 4-year-old child tells a story about a monster under their bed and insists it is real. Is this normal?",', '["No, suspect psychosis", "Yes, magical thinking and difficulty distinguishing fantasy from reality are normal at this age", "No, sign of abuse", "None"]', 1, 'Magical thinking is a hallmark of Piaget''s preoperational stage (ages 2-7). (Nelson)'),
    (v_topic_id, '101: Which of the following is an expected physical growth milestone during the second year of life (12-24 months)?",', '["Growth velocity accelerates rapidly", "Growth velocity significantly slows down compared to the first year, leading to decreased appetite (physiologic anorexia)", "Weight doubles again", "None"]', 1, 'Parents often worry about decreased appetite, but it matches the slowed growth rate. (Case Files)'),
    (v_topic_id, '102: At what age should head circumference routine measurement typically stop if the child is developing normally?",', '["12 months", "24 months (2 years)", "36 months (3 years)", "5 years"]', 2, 'Routine measurement stops at 36 months unless there are specific neurologic or developmental concerns. (Harriet Lane)'),
    (v_topic_id, '103: A child is crossing the 50th percentile downwards on the growth chart, dropping to the 10th percentile for weight, while length is preserved. What is the most common cause?",', '["Genetic short stature", "Inadequate caloric intake (Failure to Thrive)", "Hypothyroidism", "Growth hormone deficiency"]', 1, 'In failure to thrive, weight drops first, followed by height, and finally head circumference. (Nelson)'),
    (v_topic_id, '104: A child''s weight and height are BOTH below the 5th percentile, but their bone age matches their chronological age. Both parents are very short. Diagnosis?",', '["Constitutional growth delay", "Familial short stature", "Celiac disease", "None"]', 1, 'Familial short stature has normal bone age; constitutional delay has delayed bone age. (Case Files)'),
    (v_topic_id, '105: A 14-year-old boy is concerned he is the shortest in his class. His bone age is 11 years. He had a normal birth weight and his parents are of average height. What is the most likely diagnosis?",', '["Growth hormone deficiency", "Familial short stature", "Constitutional growth delay (late bloomer)", "Turner syndrome"]', 2, 'Bone age is delayed, but they eventually reach a normal adult height. (Nelson)'),
    (v_topic_id, '106: When does the adolescent growth spurt typically occur in girls relative to menarche?",', '["After menarche", "Exactly at the time of menarche", "It peaks about 6-12 months BEFORE menarche", "None"]', 2, 'Growth significantly slows down after menarche. (Harriet Lane)'),
    (v_topic_id, '107: What is the first physical sign of puberty in a male?",', '["Pubic hair growth", "Voice deepening", "Testicular enlargement (volume > 4 mL or length > 2.5 cm)", "Penile lengthening"]', 2, 'Testicular enlargement (Tanner stage 2) is the herald of male puberty. (Case Files)'),
    (v_topic_id, '108: What is the first physical sign of puberty in a female?",', '["Menarche", "Pubic hair", "Breast bud development (Thelarche)", "Axillary hair"]', 2, 'Thelarche is the first sign, typically occurring between ages 8 and 13. (Nelson)'),
    (v_topic_id, '109: Precocious puberty in girls is defined as the onset of secondary sexual characteristics before what age?",', '["6 years", "8 years", "10 years", "12 years"]', 1, 'Onset before age 8 in girls and age 9 in boys is considered precocious. (Harriet Lane)'),
    (v_topic_id, '110: Delayed puberty in boys is defined as no testicular enlargement by what age?",', '["12 years", "14 years", "16 years", "18 years"]', 1, 'Evaluation for delayed puberty is warranted if there are no signs by age 14 in boys (or 13 in girls). (Case Files)'),
    (v_topic_id, '111: A parent asks when their child should have a full set of primary (deciduous) teeth. What is the correct answer?",', '["12 months", "18-24 months", "30-36 months (2.5 - 3 years)", "5 years"]', 2, 'Children typically have all 20 primary teeth by 2.5 to 3 years of age. (Nelson)'),
    (v_topic_id, '112: At what age do children typically begin to lose their primary teeth?",', '["4 years", "6 years", "8 years", "10 years"]', 1, 'The loss of the mandibular central incisors typically occurs around age 6. (Harriet Lane)'),
    (v_topic_id, '113: A 4-week-old infant has not regained their birth weight. Is this normal?",', '["Yes, it takes 2 months", "No, term infants should regain birth weight by 10-14 days of life", "Yes, if they are breastfed", "None"]', 1, 'Failure to regain birth weight by 2 weeks requires immediate evaluation for feeding issues or pathology. (Case Files)'),
    (v_topic_id, '114: By what age is a child expected to know the difference between morning and afternoon?",', '["3 years", "4 years", "5 years", "6 years"]', 2, 'Understanding basic time concepts emerges around age 5. (Nelson)'),
    (v_topic_id, '115: At what age should a child be able to skip?",', '["3 years", "4 years", "5 years", "6 years"]', 2, 'Skipping requires complex alternating balance and is a classic 5-year-old milestone. (Harriet Lane)'),
    (v_topic_id, '116: A child can stand on one foot for 2 seconds. What age?",', '["2 years", "3 years", "4 years", "5 years"]', 1, 'Standing on one foot momentarily (1-2 seconds) is a 3-year-old milestone. (Case Files)'),
    (v_topic_id, '117: At what age should a child be able to correctly name a coin (e.g., a penny or a quarter)?",', '["3 years", "4 years", "5 years", "6 years"]', 3, 'Naming coins and understanding their value begins around age 6. (Nelson)'),
    (v_topic_id, '118: A child presents with delayed motor milestones, hypotonia, and poor feeding. Physical exam reveals a prominent tongue and hypotonia. What genetic test should be considered?",', '["Fragile X", "Karyotype for Trisomy 21 (Down Syndrome)", "Microarray for DiGeorge", "None"]', 1, 'Down syndrome is a leading cause of global developmental delay with these classic features. (Case Files)'),
    (v_topic_id, '119: What is the most common inherited cause of intellectual disability in males?",', '["Down Syndrome", "Fragile X Syndrome", "Klinefelter Syndrome", "Prader-Willi Syndrome"]', 1, 'Down syndrome is the most common genetic cause, but Fragile X is the most common INHERITED cause. (Nelson)'),
    (v_topic_id, '120: A 2-year-old boy has prominent ears, a long face, macroorchidism, and delayed speech. What is the likely diagnosis?",', '["Fetal Alcohol Syndrome", "Fragile X Syndrome", "Turner Syndrome", "None"]', 1, 'Classic phenotype of Fragile X (CGG trinucleotide repeat expansion). (Harriet Lane)'),
    (v_topic_id, '121: A child with a history of severe prematurity (26 weeks) presents at 12 months with delayed walking and spastic diplegia. What is the most likely cause?",', '["Autism", "Cerebral Palsy (due to periventricular leukomalacia or intraventricular hemorrhage)", "Spinal muscular atrophy", "None"]', 1, 'Prematurity is the biggest risk factor for Cerebral Palsy. (Case Files)'),
    (v_topic_id, '122: At what age does "parallel play" transition into "associative play" (playing together loosely without a common goal)?",', '["2 years", "3 years", "4 years", "5 years"]', 1, 'Associative play is characteristic of 3-year-olds. (Nelson)'),
    (v_topic_id, '123: A 4-month-old infant is observed sitting. What is the expected capability?",', '["Sitting totally unsupported", "Sitting with support (e.g., propped on hands or held)", "Cannot sit at all", "None"]', 1, 'Truncal control is developing, allowing supported sitting. (Harriet Lane)'),
    (v_topic_id, '124: At what age does an infant typically recognize their parents and differentiate them from strangers?",', '["1 month", "2-3 months", "6 months", "9 months"]', 1, 'Visual recognition of parents occurs early, around 2-3 months. (Case Files)'),
    (v_topic_id, '125: A child has a vocabulary of exactly 1 word besides "mama" and "dada". What age?",', '["9 months", "12 months", "15 months", "18 months"]', 1, 'One specific word + mama/dada is the benchmark for 12 months. (Nelson)'),
    (v_topic_id, '126: At what age should a child be able to point to 5 body parts when asked?",', '["12 months", "15-18 months", "24 months", "36 months"]', 1, 'Pointing to body parts demonstrates receptive language, expected around 15-18 months. (Harriet Lane)'),
    (v_topic_id, '127: A child is 2 years old. They should be able to build a tower of how many blocks?",', '["2", "4", "6", "8"]', 2, 'The milestone is 6 blocks at 24 months. (Case Files)'),
    (v_topic_id, '128: A child is 3 years old. They should be able to build a tower of how many blocks?",', '["3", "6", "9", "12"]', 2, 'The milestone is 9 blocks at 36 months. (Nelson)'),
    (v_topic_id, '129: At what age should a child be able to correctly identify their friend by name?",', '["2 years", "3 years", "4 years", "5 years"]', 1, 'Naming a friend is a social milestone for a 3-year-old. (Case Files)'),
    (v_topic_id, '130: At what age does a child typically start to ask "why" questions incessantly?",', '["2 years", "3 years", "4 years", "5 years"]', 1, 'The "why" phase peaks at 3 years as curiosity expands. (Harriet Lane)'),
    (v_topic_id, '131: A 15-month-old uses a spoon but spills a lot. Is this normal?",', '["Yes, proficiency is not expected until 24 months", "No, refer to OT", "Yes, but they should only use a fork", "None"]', 0, 'Spoon use starts at 15m but is messy. (Nelson)'),
    (v_topic_id, '132: At what age does the rooting reflex typically disappear?",', '["1 month", "4 months", "8 months", "12 months"]', 1, 'Rooting (turning head when cheek is stroked) disappears by 4 months. (Case Files)'),
    (v_topic_id, '133: A 6-month-old infant is not rolling over in either direction. What is the next step?",', '["Reassure, this is normal until 9 months", "Evaluate for motor delay or hypotonia/hypertonia", "Prescribe physical therapy", "None"]', 1, 'Rolling should occur by 4-5 months. Absence at 6 months is a red flag. (Nelson)'),
    (v_topic_id, '134: A child can walk upstairs by leading with one foot, but cannot alternate feet. What age?",', '["18 months", "24 months (2 years)", "3 years", "4 years"]', 1, 'Walking up stairs "marking time" (two feet per step) is a 2-year milestone. (Harriet Lane)'),
    (v_topic_id, '135: At what age does a child typically understand the concept of "two"?', '["2 years", "3 years", "4 years", "5 years"]', 0, 'Understanding the concept of "two" (e.g., "give me two blocks") occurs at 2 years. (Case Files)'),
    (v_topic_id, '136: A child can count to 10. They are likely at least what age?",', '["2 years", "3 years", "4 years", "5 years"]', 2, 'Rote counting to 10 is usually achieved by age 4. (Nelson)'),
    (v_topic_id, '137: At what age should a child be able to cut a circle out of paper with scissors?",', '["3 years", "4 years", "5 years", "6 years"]', 1, 'Using scissors is 4 years; cutting a shape out is typically 4-5 years. (Harriet Lane)'),
    (v_topic_id, '138: A 10-month-old infant is brought to the clinic. The parent is worried they are not walking. What is the advice?",', '["Refer to PT", "Reassure the parent; independent walking is expected by 12-15 months, up to 18 months", "Order a spine X-ray", "None"]', 1, 'Not walking at 10 months is completely normal. (Case Files)'),
    (v_topic_id, '139: At what age does an infant typically develop a "pincer grasp" using the pads of the index finger and thumb?",', '["6 months", "9 months", "10-12 months", "15 months"]', 2, 'The mature pincer grasp allows the infant to feed themselves small items like Cheerios. (Nelson)'),
    (v_topic_id, '140: What is the primary difference between a 9-month-old''s pincer grasp and a 12-month-old''s?",', '["9-month uses thumb and pinky", "9-month is ''''crude'''' (pads of fingers), 12-month is mature (tips/pads)", "There is no difference", "None"]', 1, 'The 9-month grasp is often a "scissor" grasp using the sides of the fingers. (Harriet Lane)'),
    (v_topic_id, '141: At what age should a child be able to draw a square?",', '["3 years", "4-5 years", "6 years", "7 years"]', 1, 'Circle (3), Cross (4), Square (4.5), Triangle (5). (Case Files)'),
    (v_topic_id, '142: A child can catch a bounced ball most of the time. What age?",', '["2 years", "3 years", "4 years", "5 years"]', 2, 'Catching a bounced ball requires hand-eye coordination developed by 4 years. (Nelson)'),
    (v_topic_id, '143: At what age should a child be able to copy a triangle?",', '["3 years", "4 years", "5 years", "6 years"]', 2, 'Triangle is a 5-year-old fine motor milestone. (Harriet Lane)'),
    (v_topic_id, '144: A 3-year-old child should have speech that is what percentage intelligible to a stranger?",', '["25%", "50%", "75%", "100%"]', 2, 'Rule of 4s: 2/4 (50%) at age 2, 3/4 (75%) at age 3. (Case Files)'),
    (v_topic_id, '145: A child has a vocabulary of 50 words and puts two words together (e.g., "more milk"). What age?",', '["18 months", "24 months (2 years)", "3 years", "4 years"]', 1, 'This is the classic definition of a 2-year-old''s expressive language. (Nelson)'),
    (v_topic_id, '146: At what age does an infant typically start to combine syllables like "dada" and "mama" without meaning (babbling)?",', '["4 months", "6 months", "9 months", "12 months"]', 1, 'Babbling begins at 6 months. By 9 months, it becomes more complex. (Harriet Lane)'),
    (v_topic_id, '147: An 18-month-old is evaluated for a temper tantrum. The parents report the child holds their breath until they pass out, then immediately wakes up normal. Diagnosis?",', '["Epilepsy", "Cyanotic breath-holding spell", "Arrhythmia", "None"]', 1, 'A benign, involuntary autonomic response to frustration or pain. No treatment needed. (Case Files)'),
    (v_topic_id, '148: What condition is often associated with and may exacerbate breath-holding spells in toddlers?",', '["Vitamin C deficiency", "Iron deficiency anemia", "Lead poisoning", "None"]', 1, 'Treating underlying iron deficiency often reduces the frequency of breath-holding spells. (Nelson)'),
    (v_topic_id, '149: At what age is nocturnal enuresis (bedwetting) considered abnormal and potentially warranting intervention?",', '["3 years", "5-7 years", "2 years", "10 years"]', 1, 'It is very common and considered normal up to age 5-7. Reassurance is the first line. (Harriet Lane)'),
    (v_topic_id, '150: A 6-year-old boy continues to wet the bed twice a week. He has never been dry for more than a few days. Urinalysis is normal. First-line management?",', '["Desmopressin (DDAVP)", "Imipramine", "Motivational therapy and enuresis alarms", "Fluid restriction all day"]', 2, 'Behavioral modification and bedwetting alarms have the highest long-term cure rate. (Case Files)'),
    (v_topic_id, '151: A child can dress themselves completely, including buttons, and can skip. Age?",', '["3 years", "4 years", "5 years", "6 years"]', 2, 'These are classic 5-year-old milestones. (Nelson)'),
    (v_topic_id, '152: A 2-month-old infant is not tracking objects past the midline. Next step?",', '["Reassure", "Evaluate for visual impairment", "Check for autism", "None"]', 1, 'Tracking past the midline is a key 2-month visual/motor milestone. (Harriet Lane)'),
    (v_topic_id, '153: At what age does an infant typically begin to sit alone for short periods?",', '["4 months", "6-7 months", "9 months", "12 months"]', 1, 'Propped sitting is 6 months; unsupported sitting begins around 7 months. (Case Files)'),
    (v_topic_id, '154: A 9-month-old infant is pulled to stand. What is expected?",', '["They cannot bear weight", "They bear full weight and may bounce", "They cry", "None"]', 1, 'Bearing weight on legs is expected by 6-9 months. (Nelson)'),
    (v_topic_id, '155: A child has a hand preference (is distinctly right or left-handed) at 9 months of age. What does this indicate?",', '["Normal development", "A red flag for unilateral motor deficit (e.g., hemiplegic cerebral palsy) on the non-preferred side", "Advanced intellect", "None"]', 1, 'Handedness should NOT be established before 18-24 months. Early handedness indicates weakness of the opposite side. (Case Files)'),
    (v_topic_id, '156: A child can use a fork successfully. What age?",', '["18 months", "3 years", "5 years", "7 years"]', 1, 'Spoon is 18m-24m; Fork is 3 years; Knife for spreading is 4 years. (Harriet Lane)'),
    (v_topic_id, '157: A child plays associative games and can share toys with some prompting. Age?",', '["2 years", "3 years", "4 years", "5 years"]', 1, 'Sharing is very difficult for 2-year-olds, but begins to emerge at 3 years. (Nelson)'),
    (v_topic_id, '158: At what age does an infant typically begin to "coo" (vowel sounds like "ooo" and "ahh")?",', '["1 month", "2 months", "4 months", "6 months"]', 1, 'Cooing is the primary vocalization at 2 months. (Case Files)'),
    (v_topic_id, '159: An infant laughs aloud. What is the earliest expected age?",', '["2 months", "4 months", "6 months", "8 months"]', 1, 'Laughing aloud is a classic 4-month milestone. (Nelson)'),
    (v_topic_id, '160: A child can wash and dry their hands independently. Age?",', '["2 years", "3 years", "4 years", "5 years"]', 1, 'This is a 3-year-old self-care milestone. (Harriet Lane)'),
    (v_topic_id, '161: At what age does a child typically know their own age and gender?",', '["2 years", "3 years", "4 years", "5 years"]', 1, 'Knowing age and gender is a 3-year-old milestone. (Case Files)'),
    (v_topic_id, '162: A child can tell a simple story and understands the concept of "same" and "different." Age?",', '["3 years", "4 years", "5 years", "6 years"]', 1, 'These are 4-year-old cognitive/language milestones. (Nelson)'),
    (v_topic_id, '163: A 4-month-old infant is placed on their back. What should they do with their hands?",', '["Keep them fisted", "Bring them together in the midline", "Keep them fully extended at their sides", "None"]', 1, 'Bringing hands to the midline and playing with fingers is a 4-month milestone. (Harriet Lane)'),
    (v_topic_id, '164: At what age does a child typically start to walk up and down stairs independently, alternating feet?",', '["2 years", "3 years", "4 years", "5 years"]', 2, 'Up alternating is 3; Down alternating is 4. (Case Files)'),
    (v_topic_id, '165: A 12-month-old child has a vocabulary of zero words (not even mama/dada). Is this normal?",', '["Yes, up to 18 months", "No, requires evaluation for hearing loss or developmental delay", "Yes, if they are walking", "None"]', 1, 'Lack of any words by 12-15 months is a red flag. (Nelson)'),
    (v_topic_id, '166: A child can name one color and knows what to do if they are cold, tired, or hungry. Age?",', '["3 years", "4 years", "5 years", "6 years"]', 1, 'These are 4-year-old milestones. (Harriet Lane)'),
    (v_topic_id, '167: At what age does an infant typically show an "anticipatory posture" (reaching out arms when about to be picked up)?",', '["2 months", "4 months", "6 months", "9 months"]', 2, 'This is an early social/motor milestone seen around 6 months. (Case Files)'),
    (v_topic_id, '168: A child points to 3 pictures in a book when asked. Age?",', '["12 months", "18 months", "24 months", "36 months"]', 1, 'Receptive language milestone at 18 months. (Nelson)'),
    (v_topic_id, '169: A child can say 3-word sentences. Age?",', '["2 years", "3 years", "4 years", "5 years"]', 1, 'Rule of thumb: 1 word at 1 year, 2 words at 2 years, 3 words at 3 years. (Case Files)'),
    (v_topic_id, '170: A child can brush their teeth with supervision. Age?",', '["2 years", "3 years", "4 years", "5 years"]', 1, 'A 3-year-old can brush with help; a 4-year-old can brush independently (though parents should still verify). (Harriet Lane)'),
    (v_topic_id, '171: At what age should a child be able to hop forward on one foot?",', '["3 years", "4 years", "5 years", "6 years"]', 1, 'Hopping on one foot is a 4-year-old gross motor skill. (Nelson)'),
    (v_topic_id, '172: A child can draw a person with at least 3 parts. Age?",', '["3 years", "4 years", "5 years", "6 years"]', 1, '3 parts = 4 years. 6 parts = 5 years. (Case Files)'),
    (v_topic_id, '173: A 12-month-old infant plays with a shape sorter. What do they do?",', '["Correctly match all shapes", "Bang the blocks together or drop them in a cup", "Ignore them", "None"]', 1, 'A 12-month-old can bang blocks together and release an object voluntarily into a cup. (Nelson)'),
    (v_topic_id, '174: At what age does an infant typically learn to voluntarily release an object (e.g., give a toy to a parent upon request)?",', '["6 months", "9 months", "12 months", "15 months"]', 2, 'Involuntary release happens earlier, but voluntary, precise release is 12 months. (Harriet Lane)'),
    (v_topic_id, '175: A child can run well, but falls often when trying to stop or turn. Age?",', '["15 months", "18 months", "24 months", "36 months"]', 1, 'An 18-month-old runs stiffly. A 24-month-old runs well. (Case Files)'),
    (v_topic_id, '176: A parent reports their 3-year-old child frequently repeats words and phrases exactly as they hear them on TV (echolalia). Is this normal?",', '["Yes, it''s how they learn", "No, persistent echolalia past age 30 months is a red flag for autism or language disorder", "Yes, if they are bilingual", "None"]', 1, 'Some echolalia is normal in early language acquisition, but should fade by 2.5-3 years. (Nelson)'),
    (v_topic_id, '177: A child can name all letters of the alphabet and counts to 20. Age?",', '["3 years", "4 years", "5 years", "6 years"]', 2, 'These are kindergarten-readiness skills expected around 5 years. (Harriet Lane)'),
    (v_topic_id, '178: A 6-month-old infant is examined. They have poor head control when pulled to sit. What is the diagnosis?",', '["Normal", "Hypotonia/Motor delay", "Hypertonia", "None"]', 1, 'Head lag should be completely gone by 4-5 months. (Case Files)'),
    (v_topic_id, '179: A 9-month-old infant does NOT sit independently. Next step?",', '["Reassure", "Evaluate for motor delay", "Check calcium", "None"]', 1, 'Independent sitting is expected by 7-8 months. Absence at 9 months is a red flag. (Nelson)'),
    (v_topic_id, '180: A child uses a fork, draws a square, and plays cooperatively. Age?",', '["3 years", "4-5 years", "6 years", "7 years"]', 1, 'These are combination milestones pointing to a 4 to 5-year-old. (Case Files)'),
    (v_topic_id, '181: A child can ride a scooter, balance on one foot for 10 seconds, and tie their shoes. Age?",', '["4 years", "5 years", "6 years", "7 years"]', 1, 'Tying shoes and 10-second balance point to 5 years. (Nelson)'),
    (v_topic_id, '182: What is the most common cause of failure to thrive in infants?",', '["Genetic disorder", "Inadequate caloric intake (often due to formula mixing errors or poor feeding mechanics)", "Malabsorption (Celiac)", "Congenital heart disease"]', 1, 'While organic causes exist, psychosocial/nutritional factors are the most common. (Harriet Lane)'),
    (v_topic_id, '183: A breastfed infant presents with bowing of the legs (genu varum), widened wrists, and a widened anterior fontanelle. Diagnosis?",', '["Child abuse", "Nutritional Rickets (Vitamin D deficiency)", "Scurvy", "None"]', 1, 'Breast milk is deficient in Vitamin D. Supplementation is required. (Case Files)'),
    (v_topic_id, '184: A child with autism is referred for early intervention. What is the most evidence-based therapeutic approach?",', '["Psychoanalysis", "Applied Behavior Analysis (ABA)", "Chelation therapy", "None"]', 1, 'ABA is the gold standard behavioral intervention for autism. (Nelson)'),
    (v_topic_id, '185: A child has a vocabulary of 10 words, points to communicate, and walks well. Age?",', '["12 months", "15 months", "18 months", "24 months"]', 2, 'The vocabulary points perfectly to 15-18 months. (Harriet Lane)'),
    (v_topic_id, '186: A child can identify 4 body parts, feed themselves with a spoon, and run stiffly. Age?",', '["12 months", "15-18 months", "24 months", "36 months"]', 1, 'Running stiffly and 15-20 words/parts is classic for 18 months. (Case Files)'),
    (v_topic_id, '187: At what age does an infant typically start to crawl?",', '["4-6 months", "7-9 months", "10-12 months", "14 months"]', 1, 'Crawling (creeping) emerges around 8 months. (Nelson)'),
    (v_topic_id, '188: A 6-month-old infant is introduced to pureed foods. What is the most appropriate first food to introduce?",', '["Cow''s milk", "Iron-fortified infant cereal or pureed meats", "Honey", "Fruit juice"]', 1, 'Iron stores are depleting; iron-rich foods are critical. (Harriet Lane)'),
    (v_topic_id, '189: Why is honey strictly contraindicated in infants under 12 months of age?",', '["Causes cavities", "Risk of Infant Botulism (Clostridium botulinum spores)", "Too much sugar", "Causes obesity"]', 1, 'Infants lack the gut flora to outcompete the spores. (Case Files)'),
    (v_topic_id, '190: A child can walk upstairs alternating feet, but walks downstairs with two feet per step. Age?",', '["2 years", "3 years", "4 years", "5 years"]', 1, 'Up alternating is 3 years. (Nelson)'),
    (v_topic_id, '191: A child can walk downstairs alternating feet. Age?",', '["2 years", "3 years", "4 years", "5 years"]', 2, 'Down alternating is 4 years. (Harriet Lane)'),
    (v_topic_id, '192: A child can name their best friend and understands the concept of "yesterday" vs "tomorrow". Age?",', '["3 years", "4 years", "5 years", "6 years"]', 1, 'Understanding temporal concepts like yesterday/tomorrow develops around 4-5 years. (Case Files)'),
    (v_topic_id, '193: A 2-year-old child presents with bowed legs. Is this a concern?",', '["Yes, indicates Rickets", "No, physiologic genu varum is normal until about 2 years of age", "Yes, requires surgery", "None"]', 1, 'Legs transition from varus (bowed) to straight to valgus (knock-kneed) by age 3-4, then straighten again. (Nelson)'),
    (v_topic_id, '194: At what age is physiologic knock-knees (genu valgum) most prominent?",', '["1 year", "3-4 years", "7 years", "10 years"]', 1, 'It peaks at 3-4 years and resolves by age 7. (Harriet Lane)'),
    (v_topic_id, '195: A child has a vocabulary of 250 words and speaks in 3-word phrases. Age?",', '["2 years", "3 years", "4 years", "5 years"]', 1, 'Vocabulary explodes between 2 and 3; 3-word phrases indicate a 3-year-old. (Case Files)'),
    (v_topic_id, '196: A child can copy a cross and draw a square. Age?",', '["2 years", "3 years", "4.5 years", "6 years"]', 2, 'Cross is 4, Square is 4.5. (Nelson)'),
    (v_topic_id, '197: A child can dress themselves without supervision, including tying shoes. Age?",', '["3 years", "4 years", "5 years", "6 years"]', 2, 'Tying shoes is the defining milestone here. (Harriet Lane)'),
    (v_topic_id, '198: At what age do children typically establish "theory of mind" (understanding that others have different thoughts/beliefs)?",', '["2 years", "3 years", "4-5 years", "7 years"]', 2, 'Demonstrated by passing the "false belief" test. (Case Files)'),
    (v_topic_id, '199: A child is referred for stuttering. They are 3 years old and repeat the first syllable of words occasionally without tension. Management?",', '["Immediate speech therapy", "Reassure parents; developmental dysfluency is common and usually resolves by age 4-5", "Refer to neurology", "None"]', 1, 'True stuttering (with facial tension/frustration) or persistence past age 5 requires therapy. (Nelson)'),
    (v_topic_id, '200: A 12-month-old infant uses "jargon" (babbling with adult-like intonation and rhythm). Is this normal?",', '["No", "Yes, this is a normal precursor to expressive language", "Indicates autism", "None"]', 1, 'Jargoning is very common around the first birthday. (Case Files)'),
    (v_topic_id, '201: A child can stand on one foot for 5 seconds. What is their likely age?",', '["3 years", "4 years", "5 years", "6 years"]', 1, '2 seconds = 3 years; 5 seconds = 4 years; 10 seconds = 5 years. (Nelson)'),
    (v_topic_id, '202: Which of the following is a "red flag" requiring immediate evaluation in a 24-month-old?",', '["Cannot ride a tricycle", "Cannot tie shoes", "Lack of 2-word spontaneous phrases", "Cannot jump forward"]', 2, 'No 2-word phrases by 24 months is a major red flag for language delay or autism. (Harriet Lane)'),
    (v_topic_id, '203: A child can walk upstairs and downstairs alternating feet without holding a rail. Age?",', '["2 years", "3 years", "4 years", "5 years"]', 2, 'Walking downstairs alternating feet without support is definitively a 4-year-old skill. (Case Files)'),
    (v_topic_id, '204: A 3-year-old child should have how many primary teeth?",', '["10", "16", "20", "32"]', 2, 'All 20 primary teeth should be erupted by age 2.5 to 3 years. (Nelson)'),
    (v_topic_id, '205: A parent asks when their child will start to lose their baby teeth. The first to fall out are usually the:",', '["Maxillary central incisors", "Mandibular central incisors", "First molars", "Canines"]', 1, 'The mandibular central incisors erupt first and fall out first, usually around age 6. (Harriet Lane)'),
    (v_topic_id, '206: A 6-month-old infant is observed sitting. Their back is rounded and they require their hands for support. Is this normal?",', '["Yes, this is the classic ''''tripod'''' sitting posture", "No, indicates hypotonia", "No, indicates hypertonia", "None"]', 0, 'Tripod sitting is a normal transitional phase to unsupported sitting (8 months). (Case Files)'),
    (v_topic_id, '207: At what age does an infant typically start pulling to a stand?",', '["6 months", "9 months", "12 months", "15 months"]', 1, 'Pulling to a stand and cruising along furniture happens at 9 months. (Nelson)'),
    (v_topic_id, '208: A child has a vocabulary of exactly 50 words. They are likely what age?",', '["18 months", "24 months (2 years)", "30 months", "36 months"]', 1, 'A 2-year-old has 50+ words. An 18-month-old has 10-25 words. (Harriet Lane)'),
    (v_topic_id, '209: A child engages in "solitary play" and treats other children like objects. Age?",', '["1 year", "2 years", "3 years", "4 years"]', 0, 'Solitary play is typical for infants and 1-year-olds. (Case Files)'),
    (v_topic_id, '210: At what age does a child typically start drawing a person with at least 6 body parts?",', '["3 years", "4 years", "5 years", "6 years"]', 2, '5 years = 6 body parts. 4 years = 3 body parts. (Nelson)'),
    (v_topic_id, '211: A child can count 10 objects correctly (one-to-one correspondence). Age?",', '["3 years", "4 years", "5 years", "6 years"]', 2, 'Counting 10 objects accurately is a kindergarten skill (5 years). (Harriet Lane)'),
    (v_topic_id, '212: A 15-month-old points to the refrigerator and says "ba" to request their bottle. What does this indicate?",', '["Expressive language delay", "Normal use of proto-declarative pointing and a word approximation", "Autism", "None"]', 1, 'Using a word approximation ("ba") and pointing to request an object is normal for 15 months. (Case Files)'),
    (v_topic_id, '213: At what age is the palmar grasp reflex expected to disappear?",', '["1-2 months", "3-4 months", "6-8 months", "12 months"]', 1, 'It must disappear by 3-4 months so the infant can intentionally reach and grasp. (Nelson)'),
    (v_topic_id, '214: A child is 3 years old. They should be able to state their:",', '["First name only", "First and last name, age, and gender", "Phone number", "Address"]', 1, 'Stating first/last name, age, and gender are 3-year-old milestones. (Harriet Lane)'),
    (v_topic_id, '215: A 4-year-old child should be able to hop on one foot how many times?",', '["They cannot hop", "1-2 times", "5-10 times", "Indefinitely"]', 1, 'Hopping 1-2 times on one foot is a 4-year-old milestone. (Case Files)'),
    (v_topic_id, '216: At what age does an infant typically double their birth length?",', '["1 year", "2 years", "3 years", "4 years"]', 3, 'Birth length (50 cm) increases by 50% at 1 year (75 cm) and doubles by 4 years (100 cm). (Nelson)'),
    (v_topic_id, '217: A child is 2 years old. What percentage of their adult height have they typically reached?",', '["25%", "50%", "75%", "90%"]', 1, 'A child''s height at 2 years of age is approximately half of their final adult height. (Harriet Lane)'),
    (v_topic_id, '218: At what age should a child understand the prepositions "on," "in," and "under"?",', '["2 years", "3 years", "4 years", "5 years"]', 1, 'Understanding prepositions is a classic 3-year-old receptive language milestone. (Case Files)'),
    (v_topic_id, '219: A child is examined for school readiness. They can copy a triangle, draw a person with 6 parts, and count to 10. They are most likely entering what grade?",', '["Preschool", "Kindergarten (Age 5)", "1st Grade (Age 6)", "2nd Grade"]', 1, 'These are classic 5-year-old milestones. (Nelson)'),
    (v_topic_id, '220: A 10-month-old infant is observed dropping a toy repeatedly and watching it fall. What developmental concept is this?",', '["Autism", "Understanding cause and effect", "Hyperactivity", "None"]', 1, 'A normal cognitive stage where they learn that actions have predictable consequences. (Harriet Lane)'),
    (v_topic_id, '221: At what age should an infant be able to roll from their back (supine) to their tummy (prone)?",', '["2 months", "4 months", "5-6 months", "8 months"]', 2, 'Front-to-back happens first (4m); back-to-front requires more coordination (5-6m). (Case Files)'),
    (v_topic_id, '222: A 2-year-old child is frustrated and bites a playmate. Is this abnormal?",', '["Yes, refer to psychiatry", "No, biting is a common manifestation of frustration in toddlers with limited expressive language", "Yes, sign of abuse", "None"]', 1, 'It is normal toddler behavior, but parents must consistently discourage it. (Nelson)'),
    (v_topic_id, '223: A parent brings in a 5-year-old who stutters when excited. It started 6 months ago. What is the recommendation?",', '["Ignore it", "Speech therapy referral; stuttering persisting > 6 months or past age 5 warrants intervention", "Medication", "None"]', 1, 'While developmental dysfluency is common at 3-4, persistence at 5 requires therapy. (Harriet Lane)'),
    (v_topic_id, '224: A child can say a 5-word sentence and tells long, involved stories. Their speech is 100% intelligible. Age?",', '["3 years", "4 years", "5 years", "6 years"]', 1, 'These are 4-year-old expressive language milestones. (Case Files)'),
    (v_topic_id, '225: A child has an imaginary friend. This is most common at what age?",', '["2 years", "4 years", "7 years", "10 years"]', 1, 'Imaginary friends are a normal part of preschool (3-5 years) magical thinking. (Nelson)'),
    (v_topic_id, '226: A 6-month-old infant does not turn their head to the sound of a bell. Next step?",', '["Reassure", "Order an audiogram immediately", "Wait until 9 months", "Order an MRI"]', 1, 'Failure to orient to sound by 6 months is a major red flag for hearing loss. (Harriet Lane)'),
    (v_topic_id, '227: A child is referred for "clumsiness." They are 3 years old and cannot ride a tricycle or stand on one foot for 2 seconds. Is this a delay?",', '["No", "Yes, these are 3-year-old milestones they should have achieved", "Yes, but they are 5-year milestones", "None"]', 1, 'A 3-year-old should ride a trike and balance briefly on one foot. (Case Files)'),
    (v_topic_id, '228: At what age does a child typically learn to zip a zipper (once engaged)?",', '["3 years", "4 years", "5 years", "6 years"]', 1, 'A 4-year-old can zip and button. (Nelson)'),
    (v_topic_id, '229: A 12-month-old infant is not pointing to objects. What is the most appropriate action?",', '["Reassure", "Perform a formal autism screening (e.g., M-CHAT) and refer for early intervention", "Order an EEG", "None"]', 1, 'Lack of pointing (joint attention) at 12 months is a major red flag for autism. (Harriet Lane)'),
    (v_topic_id, '230: A child can draw a circle and a cross, but not a square. What is their likely age?",', '["3 years", "4 years", "5 years", "6 years"]', 1, 'A 4-year-old can draw a cross. A square is drawn at 4.5 to 5 years. (Case Files)'),
    (v_topic_id, '231: At what age should an infant be able to hold their head steady when held in a sitting position?",', '["1 month", "2 months", "4 months", "6 months"]', 2, 'Head control should be solid by 4 months. (Nelson)'),
    (v_topic_id, '232: A child knows 4 colors and can play a simple board game. Age?",', '["3 years", "4 years", "5 years", "6 years"]', 1, 'These are classic 4-year-old milestones. (Harriet Lane)'),
    (v_topic_id, '233: A child can use a knife to spread butter or jelly. Age?",', '["3 years", "4 years", "5 years", "6 years"]', 1, 'Spreading with a knife is a 4-year-old fine motor skill. (Case Files)'),
    (v_topic_id, '234: A child can cut out a complex shape with scissors. Age?",', '["3 years", "4 years", "5 years", "6 years"]', 2, 'Cutting a simple shape is 4 years; a complex shape is 5 years. (Nelson)'),
    (v_topic_id, '235: At what age does an infant typically start to "creep" (crawl on hands and knees)?",', '["6 months", "8-9 months", "12 months", "15 months"]', 1, 'True hands-and-knees crawling emerges around 8-9 months. (Harriet Lane)'),
    (v_topic_id, '236: A child walks with a mature gait (heel-to-toe progression). What age?",', '["1 year", "2 years", "3 years", "4 years"]', 2, 'The wide-based, flat-footed toddler gait matures to heel-toe by age 3. (Case Files)'),
    (v_topic_id, '237: A child is 5 years old. They should be able to skip using what pattern?",', '["They cannot skip", "Skipping on one foot only", "Skipping alternating feet", "None"]', 2, 'Alternating skipping is the hallmark of 5-year-old gross motor development. (Nelson)'),
    (v_topic_id, '238: A 15-month-old child has a vocabulary of 5 words. Is this normal?",', '["No", "Yes, 15-month-olds typically have 3-5 words", "Indicates autism", "None"]', 1, '12m = 1 word; 15m = 3-5 words; 18m = 10-25 words; 24m = 50+ words. (Harriet Lane)'),
    (v_topic_id, '239: A child can correctly identify their right and left hand. Age?",', '["3 years", "4 years", "5 years", "6 years"]', 2, 'Right/left discrimination on oneself is a 5-year-old cognitive milestone. (Case Files)'),
    (v_topic_id, '240: At what age does a child typically start to understand the concept of "yesterday"?', '["3 years", "4-5 years", "6-7 years", "8 years"]', 1, 'Temporal concepts (yesterday, today, tomorrow) solidify around age 4-5. (Nelson)'),
    (v_topic_id, '241: A child is observed playing a game of "tag" with friends, understanding the rules of being "it." Age?",', '["3 years", "4 years", "5 years", "6 years"]', 2, 'Rule-based, competitive games begin around age 5 (Kindergarten). (Harriet Lane)'),
    (v_topic_id, '242: A 2-year-old child should be able to do which of the following?",', '["Draw a square", "Run well and kick a ball", "Ride a tricycle", "Hop on one foot"]', 1, 'Running well and kicking a ball are classic 2-year-old gross motor milestones. (Case Files)'),
    (v_topic_id, '243: A child can name all the days of the week. Age?",', '["3 years", "4 years", "5 years", "6 years"]', 2, 'Days of the week are typically mastered at age 5. (Nelson)'),
    (v_topic_id, '244: A 9-month-old infant is not babbling. Next step?",', '["Reassure", "Order an audiogram (Hearing test)", "Check for autism", "None"]', 1, 'Absence of babbling by 9 months requires ruling out hearing loss. (Harriet Lane)'),
    (v_topic_id, '245: A 4-year-old child should be able to follow a command with how many steps?",', '["1 step", "2 steps", "3 steps", "4 steps"]', 3, '4-year-olds can follow 4-step commands. (Case Files)'),
    (v_topic_id, '246: A child understands the difference between a dog and a cat, but calls all four-legged animals "dog." This is an example of:",', '["Overextension", "Echolalia", "Stuttering", "None"]', 0, 'A normal phase of early language development (ages 1-2). (Nelson)'),
    (v_topic_id, '247: At what age does a child typically start to use the word "no" meaningfully (and frequently)?",', '["12 months", "15-18 months", "24 months", "36 months"]', 1, 'The "no" phase starts around 15-18 months as they exert autonomy. (Harriet Lane)'),
    (v_topic_id, '248: A child can draw a line, but not a circle. Age?",', '["1 year", "2 years", "3 years", "4 years"]', 1, 'Drawing a vertical or horizontal line is a 2-year-old fine motor milestone. (Case Files)'),
    (v_topic_id, '249: A child is 3 years old. They should be able to build a tower of 9 blocks and a "bridge" of 3 blocks. True or False?",', '["True", "False", "Only 5-year-olds can build a bridge", "None"]', 0, 'Building a bridge of 3 blocks is a specific 3-year-old visual-motor milestone. (Nelson)'),
    (v_topic_id, '250: A child can catch a bounced ball. Age?",', '["2 years", "3 years", "4 years", "5 years"]', 2, 'Catching a bounced ball requires tracking and coordination (4 years). (Harriet Lane)'),
    (v_topic_id, '251: A 12-month-old child has a vocabulary of exactly 1 word. What is the parents'' biggest concern?",', '["Nothing, this is completely normal", "They have autism", "They have hearing loss", "None"]', 0, '1 word + mama/dada is the exact expectation for a 12-month-old. (Case Files)'),
    (v_topic_id, '252: A child can name 4 colors, count to 4, and draw a person with 4 parts. What is their likely age?",', '["3 years", "4 years", "5 years", "6 years"]', 1, 'The "Rule of 4s" makes this easy: 4 years old. (Nelson)'),
    (v_topic_id, '253: A child can dress themselves, but puts their shoes on the wrong feet. Age?",', '["3 years", "4 years", "5 years", "6 years"]', 1, 'A 4-year-old can dress themselves completely but struggles with left/right on shoes. (Harriet Lane)'),
    (v_topic_id, '254: At what age should a child be able to tie their shoelaces?",', '["3 years", "4 years", "5 years", "6 years"]', 2, 'Tying shoes is a classic 5-year-old fine motor skill. (Case Files)'),
    (v_topic_id, '255: A child is referred for "toe walking." They are 3 years old and constantly walk on their toes, never bringing the heel down. Diagnosis to rule out?",', '["Normal development", "Cerebral palsy (spastic diplegia) or Muscular dystrophy", "Autism", "None"]', 1, 'Persistent toe walking past age 2 or 3 is a red flag for neuromuscular disease. (Nelson)'),
    (v_topic_id, '256: A child can tell a long story, but the events are completely out of order. Age?",', '["2 years", "3 years", "4 years", "5 years"]', 1, 'A 3-year-old can tell a story, but sequence/logic develops closer to 4-5 years. (Harriet Lane)'),
    (v_topic_id, '257: A child is 5 years old. They should have a vocabulary of how many words?",', '["50", "200", "500", "2000+"]', 3, 'By age 5, a child has a vocabulary of >2000 words and speaks in full, complex sentences. (Case Files)'),
    (v_topic_id, '258: A child has a persistent Moro reflex at 6 months of age. What does this indicate?",', '["Normal", "Upper motor neuron lesion (e.g., Cerebral Palsy)", "Lower motor neuron lesion", "None"]', 1, 'Primitive reflexes should disappear by 4-6 months; persistence implies cortical damage. (Nelson)'),
    (v_topic_id, '259: A 2-month-old infant is not cooing. Is this a delay?",', '["Yes", "No, cooing starts at 4 months", "Yes, but wait until 6 months to evaluate", "None"]', 0, 'Cooing is the primary expected vocalization at 2 months. (Harriet Lane)'),
    (v_topic_id, '260: A child can point to 1 body part when named. Age?",', '["12 months", "15 months", "18 months", "24 months"]', 1, 'Pointing to 1 body part is a 15-month milestone. Pointing to 3+ is an 18-month milestone. (Case Files)'),
    (v_topic_id, '261: A child can combine 2 syllables (e.g., "da-da") but does not apply them to the father specifically. Age?",', '["6 months", "9 months", "12 months", "15 months"]', 1, 'Non-specific babbling of "dada" or "mama" is a 9-month milestone. (Nelson)'),
    (v_topic_id, '262: A child can build a tower of 6 cubes. Age?",', '["15 months", "18 months", "24 months (2 years)", "3 years"]', 2, '24 months = 6 cubes. (Harriet Lane)'),
    (v_topic_id, '263: A child can run stiffly and walk up stairs while holding a hand. Age?",', '["12 months", "18 months", "24 months", "36 months"]', 1, 'Running stiffly is the gross motor milestone for an 18-month-old. (Case Files)'),
    (v_topic_id, '264: A child can say 2-word phrases and follows a 2-step command. Age?",', '["18 months", "2 years", "3 years", "4 years"]', 1, 'The "Rule of 2s" for a 2-year-old. (Nelson)'),
    (v_topic_id, '265: A child has an vocabulary of 50 words and their speech is 50% intelligible. Age?",', '["18 months", "2 years", "3 years", "4 years"]', 1, '50 words and 50% intelligible = 2 years old. (Harriet Lane)'),
    (v_topic_id, '266: A child can say 3-word sentences and their speech is 75% intelligible. Age?",', '["2 years", "3 years", "4 years", "5 years"]', 1, '3-word sentences and 75% intelligible = 3 years old. (Case Files)'),
    (v_topic_id, '267: A child can ride a tricycle and copy a circle. Age?",', '["2 years", "3 years", "4 years", "5 years"]', 1, 'Tricycle and circle = 3 years old. (Nelson)'),
    (v_topic_id, '268: A child can hop on one foot and copy a cross. Age?",', '["3 years", "4 years", "5 years", "6 years"]', 1, 'Hop on one foot and copy a cross = 4 years old. (Harriet Lane)'),
    (v_topic_id, '269: A child can skip and copy a triangle. Age?",', '["3 years", "4 years", "5 years", "6 years"]', 2, 'Skip and copy a triangle = 5 years old. (Case Files)'),
    (v_topic_id, '270: A child has object permanence and a crude pincer grasp. Age?",', '["6 months", "9 months", "12 months", "15 months"]', 1, 'Object permanence and crude pincer = 9 months old. (Nelson)'),
    (v_topic_id, '271: A child has a mature pincer grasp and says 1 word. Age?",', '["9 months", "12 months", "15 months", "18 months"]', 1, 'Mature pincer and 1 word = 12 months old. (Harriet Lane)'),
    (v_topic_id, '272: A child can sit without support and transfers objects from hand to hand. Age?",', '["4 months", "6 months", "9 months", "12 months"]', 1, 'Transfers objects = 6 months old. (Case Files)'),
    (v_topic_id, '273: A child rolls front-to-back and laughs aloud. Age?",', '["2 months", "4 months", "6 months", "9 months"]', 1, 'Rolls front-to-back and laughs = 4 months old. (Nelson)'),
    (v_topic_id, '274: A child lifts their head 45 degrees prone and has a social smile. Age?",', '["1 month", "2 months", "4 months", "6 months"]', 1, 'Social smile = 2 months old. (Harriet Lane)'),
    (v_topic_id, '275: A child uses a spoon well and runs well. Age?",', '["18 months", "24 months (2 years)", "3 years", "4 years"]', 1, 'Runs well and uses spoon = 2 years old. (Case Files)'),
    (v_topic_id, '276: A child can unbutton buttons and take off their clothes. Age?",', '["2 years", "3 years", "4 years", "5 years"]', 1, 'Unbuttoning/undressing = 3 years old. (Nelson)'),
    (v_topic_id, '277: A child can button buttons and get dressed completely. Age?",', '["3 years", "4 years", "5 years", "6 years"]', 1, 'Buttoning/dressing completely = 4 years old. (Harriet Lane)'),
    (v_topic_id, '278: A child engages in associative play. Age?",', '["2 years", "3 years", "4 years", "5 years"]', 1, 'Associative play = 3 years old. (Case Files)'),
    (v_topic_id, '279: A child engages in cooperative play with rules. Age?",', '["3 years", "4 years", "5 years", "6 years"]', 1, 'Cooperative play = 4 years old. (Nelson)'),
    (v_topic_id, '280: A child has stranger anxiety. When does this typically start?",', '["4 months", "6-9 months", "12 months", "18 months"]', 1, 'Starts around 6-9 months. (Harriet Lane)'),
    (v_topic_id, '281: A child has separation anxiety. When does this typically peak?",', '["6 months", "12-18 months", "24 months", "36 months"]', 1, 'Peaks around 12-18 months. (Case Files)'),
    (v_topic_id, '282: At what age does a child typically start drawing a person with 3 body parts?",', '["2 years", "3 years", "4 years", "5 years"]', 2, 'Drawing a person with 3 parts is a 4-year-old milestone. (Nelson)'),
    (v_topic_id, '283: A child can stand on one foot for 1-2 seconds. Age?",', '["2 years", "3 years", "4 years", "5 years"]', 1, 'Momentary balance on one foot is a 3-year-old milestone. (Harriet Lane)'),
    (v_topic_id, '284: A child can count 3 objects and knows 3 colors. Age?",', '["2 years", "3 years", "4 years", "5 years"]', 1, 'The "Rule of 3s" applies to a 3-year-old. (Case Files)'),
    (v_topic_id, '285: At what age should a child be able to tie a knot?",', '["3 years", "4 years", "5 years", "6 years"]', 2, 'Tying a knot is a 5-year-old milestone, preceding tying a bow/shoelaces. (Nelson)'),
    (v_topic_id, '286: A child can catch a tossed ball with two hands. Age?",', '["2 years", "3 years", "4 years", "5 years"]', 1, 'Catching a large tossed ball is typically achieved around 3 years. (Harriet Lane)'),
    (v_topic_id, '287: A child can kick a ball forward. Age?",', '["12 months", "18 months", "24 months", "36 months"]', 2, 'Kicking a ball is a classic 24-month (2-year) gross motor skill. (Case Files)'),
    (v_topic_id, '288: A child can throw a ball overhand. Age?",', '["12 months", "18 months", "24 months", "36 months"]', 1, 'Throwing a ball overhand begins around 18 months. (Nelson)'),
    (v_topic_id, '289: At what age does an infant typically start to drink from a cup independently?",', '["9 months", "12 months", "15 months", "18 months"]', 1, 'Drinking from a cup without help is achieved around 12 months. (Harriet Lane)'),
    (v_topic_id, '290: A child can use a spoon but spills a little. Age?",', '["12 months", "15-18 months", "24 months", "36 months"]', 1, 'Spoon use starts at 15-18 months, with mastery by 24 months. (Case Files)'),
    (v_topic_id, '291: A child can jump in place with both feet off the floor. Age?",', '["18 months", "24 months (2 years)", "3 years", "4 years"]', 1, 'Jumping in place is a 24-month milestone. (Nelson)'),
    (v_topic_id, '292: A child can broad jump (jump forward). Age?",', '["2 years", "3 years", "4 years", "5 years"]', 1, 'Broad jumping requires more coordination and is a 3-year-old skill. (Harriet Lane)'),
    (v_topic_id, '293: A child can pedal a tricycle. Age?",', '["2 years", "3 years", "4 years", "5 years"]', 1, 'Pedaling a tricycle is the classic 3-year gross motor milestone. (Case Files)'),
    (v_topic_id, '294: A child can draw a straight line. Age?",', '["1 year", "2 years", "3 years", "4 years"]', 1, 'Drawing a vertical/horizontal line is a 2-year fine motor skill. (Nelson)'),
    (v_topic_id, '295: A child can build a tower of 2 cubes. Age?",', '["9 months", "12 months", "15 months", "18 months"]', 2, 'A 15-month-old can build a tower of 2 cubes. (Harriet Lane)'),
    (v_topic_id, '296: A child can build a tower of 4 cubes. Age?",', '["15 months", "18 months", "24 months", "36 months"]', 1, 'An 18-month-old can build a tower of 3-4 cubes. (Case Files)'),
    (v_topic_id, '297: A child points to objects to show them to others (protodeclarative pointing). Age?",', '["9 months", "12-15 months", "18 months", "24 months"]', 1, 'This joint attention behavior emerges between 12 and 15 months. (Nelson)'),
    (v_topic_id, '298: A child points to objects to request them (protoimperative pointing). Age?",', '["6 months", "9 months", "12 months", "15 months"]', 2, 'Requesting points emerge earlier (12 months) than sharing points. (Harriet Lane)'),
    (v_topic_id, '299: A child understands "no" and stops what they are doing briefly. Age?",', '["6 months", "9 months", "12 months", "18 months"]', 1, 'Understanding "no" is an important 9-month receptive language milestone. (Case Files)'),
    (v_topic_id, '300: A child can follow a 1-step command with a gesture (e.g., "give me the ball" while holding hand out). Age?",', '["9 months", "12 months", "15 months", "18 months"]', 1, 'Following a 1-step command WITH a gesture is a 12-month milestone. (Nelson)'),
    (v_topic_id, '301: A child can follow a 1-step command WITHOUT a gesture. Age?",', '["12 months", "15 months", "18 months", "24 months"]', 1, 'Following a 1-step command without a visual cue is a 15-month milestone. (Harriet Lane)'),
    (v_topic_id, '302: A child can say 10-25 words. Age?",', '["12 months", "15 months", "18 months", "24 months"]', 2, '18 months is the age of the vocabulary "explosion" starting. (Case Files)'),
    (v_topic_id, '303: A child can name 1 picture in a book. Age?",', '["12 months", "15 months", "18 months", "24 months"]', 2, 'Naming a picture is an 18-month expressive language milestone. (Nelson)'),
    (v_topic_id, '304: A child can name 6 body parts. Age?",', '["18 months", "24 months", "3 years", "4 years"]', 1, 'Naming 6 body parts is a 24-month (2-year) milestone. (Harriet Lane)'),
    (v_topic_id, '305: A child asks "what" and "where" questions. Age?",', '["2 years", "3 years", "4 years", "5 years"]', 1, 'The "what/where" phase begins around age 3 (along with "why"). (Case Files)'),
    (v_topic_id, '306: A child can distinguish fantasy from reality. Age?",', '["3 years", "4 years", "5 years", "school age (7+ years)"]', 3, 'Magical thinking persists until the concrete operational stage (age 7). (Nelson)'),
    (v_topic_id, '307: A child plays "make-believe" (symbolic play). When does this emerge?",', '["12 months", "18 months", "24 months", "36 months"]', 1, 'Symbolic play begins around 18 months (e.g., feeding a doll). (Harriet Lane)'),
    (v_topic_id, '308: A child can wash and dry their hands. Age?",', '["2 years", "3 years", "4 years", "5 years"]', 1, 'Independent hand washing is a 3-year-old self-care skill. (Case Files)'),
    (v_topic_id, '309: A child can brush their teeth independently. Age?",', '["3 years", "4 years", "5 years", "6 years"]', 1, 'A 4-year-old can brush independently, though parents should supervise. (Nelson)'),
    (v_topic_id, '310: A child can wipe themselves after using the toilet. Age?",', '["3 years", "4 years", "5 years", "6 years"]', 2, 'Independent toileting, including wiping, is typically mastered by 5 years. (Harriet Lane)'),
    (v_topic_id, '311: A child can dress themselves completely without help. Age?",', '["3 years", "4 years", "5 years", "6 years"]', 2, 'Complete independent dressing (including shoes) is a 5-year-old skill. (Case Files)'),
    (v_topic_id, '312: A child can hop on one foot for 10 seconds. Age?",', '["3 years", "4 years", "5 years", "6 years"]', 2, '10 seconds of hopping is a 5-year-old milestone. (Nelson)'),
    (v_topic_id, '313: A child can skip alternating feet. Age?",', '["3 years", "4 years", "5 years", "6 years"]', 2, 'Alternating skipping is a 5-year-old gross motor skill. (Harriet Lane)'),
    (v_topic_id, '314: A child can copy a diamond. Age?",', '["4 years", "5 years", "6 years", "7 years"]', 2, 'Diamond is the most complex shape, usually mastered at 6 years. (Case Files)'),
    (v_topic_id, '315: A child knows their right and left hand. Age?",', '["3 years", "4 years", "5 years", "6 years"]', 2, 'Right/left discrimination on oneself is a 5-year-old skill. (Nelson)'),
    (v_topic_id, '316: A child can name 4 colors. Age?",', '["2 years", "3 years", "4 years", "5 years"]', 2, 'Naming 4 colors is a 4-year-old milestone. (Harriet Lane)'),
    (v_topic_id, '317: A child can count 10 objects. Age?",', '["3 years", "4 years", "5 years", "6 years"]', 2, '1-to-1 counting of 10 objects is a 5-year-old skill. (Case Files)'),
    (v_topic_id, '318: A child''s birth weight has tripled. Age?",', '["6 months", "12 months", "24 months", "36 months"]', 1, 'Birth weight triples at 1 year. (Nelson)'),
    (v_topic_id, '319: A child''s birth weight has quadrupled. Age?",', '["1 year", "2 years", "3 years", "4 years"]', 1, 'Birth weight quadruples at 2 years. (Harriet Lane)'),
    (v_topic_id, '320: Final Pearl: When assessing a child with a speech delay, what is the single most important FIRST step?",', '["Order an MRI of the brain", "Refer to speech therapy", "Perform a formal audiology evaluation (hearing test)", "Reassure and observe"]', 2, 'You cannot speak if you cannot hear. Always rule out hearing loss first. (MediHelp Mastery)');
